<?php
/** Orchard Ledger storage workflow endpoint: facility ownership and capacity changes are validated inside a single transaction. */
declare(strict_types=1);
require_once __DIR__ . '/../../includes/bootstrap.php';
require_method('POST');verify_csrf();$providerUser=require_role(['storage_provider']);$bookingId=filter_input(INPUT_POST,'booking_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$next=normalize_text($_POST['status']??'',20);$transitions=['requested'=>['approved','rejected'],'approved'=>['active','cancelled'],'active'=>['completed','cancelled']];
if(!$bookingId)json_response(false,'A valid storage booking is required.',[],422);$pdo=db();$pdo->beginTransaction();
try{$booking=fetch_one('SELECT sb.*,sf.provider_id,sp.user_id AS provider_user_id FROM storage_bookings sb JOIN storage_facilities sf ON sf.id=sb.facility_id JOIN storage_providers sp ON sp.id=sf.provider_id WHERE sb.id=:id AND sp.user_id=:user FOR UPDATE',['id'=>$bookingId,'user'=>$providerUser['id']]);if($booking===null)throw new RuntimeException('This booking is not assigned to your storage operation.');if(!in_array($next,$transitions[$booking['status']]??[],true))throw new RuntimeException('This booking cannot move to that status.');if($next==='approved'){if((float)$booking['quantity_kg']>(float)$booking['available_capacity_kg'])throw new RuntimeException('Current facility capacity cannot cover this booking.');$pdo->prepare('UPDATE storage_facilities SET available_capacity_kg=available_capacity_kg-:quantity WHERE id=:facility')->execute(['quantity'=>$booking['quantity_kg'],'facility'=>$booking['facility_id']]);}if(in_array($next,['completed','cancelled'],true)&&in_array($booking['status'],['approved','active'],true))$pdo->prepare('UPDATE storage_facilities SET available_capacity_kg=LEAST(total_capacity_kg,available_capacity_kg+:quantity) WHERE id=:facility')->execute(['quantity'=>$booking['quantity_kg'],'facility'=>$booking['facility_id']]);$pdo->prepare('UPDATE storage_bookings SET status=:status WHERE id=:id')->execute(['status'=>$next,'id'=>$bookingId]);$pdo->prepare('INSERT INTO storage_booking_status_history (booking_id,status,changed_by_user_id,note) VALUES (:booking,:status,:actor,:note)')->execute(['booking'=>$bookingId,'status'=>$next,'actor'=>$providerUser['id'],'note'=>'Provider updated booking status.']);create_notification((int)$booking['farmer_id'],'storage_booking_'.$next,'Storage booking '.ucfirst($next),'Your storage booking '.$booking['reference_code'].' is now '.str_replace('_',' ',$next).'.','farmer/dashboard.php','storage_booking',$bookingId);$pdo->commit();audit_log((int)$providerUser['id'],'storage_booking_'.$next,'storage_bookings',$bookingId);json_response(true,'Booking status updated to '.ucfirst($next).'.',['booking_id'=>$bookingId,'status'=>$next]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(false,$e instanceof RuntimeException?$e->getMessage():'The booking status could not be updated.',[],422);}

